-- This oracle deliberately knows only the facade's raw wire.  Every fixture,
-- ceiling, digest frame, assignment projection, observation, and finding is
-- restated here; no SourceSnapshot, TrackedEntry, HaskellSubject, component
-- type, production constant, production encoder, or expected registry crosses
-- the oracle boundary.

runCompilerComponentPlanOracle :: IO ()
runCompilerComponentPlanOracle =
  finishDiagnostics
    "CompilerComponentPlanOracle"
    (registryIntegrityProblems <> fixtureIntegrityProblems <> concatMap runExactCase exactCases)

runCompilerComponentPlanSelectorOracle :: String -> IO ()
runCompilerComponentPlanSelectorOracle selector =
  finishDiagnostics
    "CompilerComponentPlanOracle selector"
    (registryIntegrityProblems <> fixtureIntegrityProblems <> assignedProblems)
 where
  targets = [target | (candidate, target) <- compilerComponentPlanSelectorIntents, candidate == selector]
  assigned = [exactCase | target <- targets, exactCase <- exactCases, exactCaseLabel exactCase == target]
  assignedProblems = case assigned of
    [exactCase] -> runExactCase exactCase
    _ ->
      [ "selector intent does not resolve to exactly one exact case: selector="
          <> selector
          <> "; targets="
          <> show targets
          <> "; exact-cases="
          <> show (map exactCaseLabel assigned)
      ]

runCompilerComponentPlanSelectorImpactOracle :: String -> IO ()
runCompilerComponentPlanSelectorImpactOracle selector =
  finishDiagnostics
    "CompilerComponentPlanOracle declared impacts"
    (registryIntegrityProblems <> fixtureIntegrityProblems <> impactProblems)
 where
  impacted = exactCasesForLabels (selectorAffectedCaseLabels selector)
  impactProblems =
    [ "declared impacted exact case remained green: selector="
        <> selector
        <> "; exact-case="
        <> exactCaseLabel exactCase
    | exactCase <- impacted
    , null (runExactCase exactCase)
    ]

runCompilerComponentPlanSelectorIsolationOracle :: String -> IO ()
runCompilerComponentPlanSelectorIsolationOracle selector =
  finishDiagnostics
    "CompilerComponentPlanOracle unaffected controls"
    (registryIntegrityProblems <> fixtureIntegrityProblems <> concatMap runExactCase unaffected)
 where
  targets = selectorAffectedCaseLabels selector
  unaffected =
    [ exactCase
    | exactCase <- exactCases
    , exactCaseLabel exactCase `notElem` targets
    ]

runCompilerComponentPlanSelectorProductControlOracle :: String -> IO ()
runCompilerComponentPlanSelectorProductControlOracle selector =
  finishDiagnostics
    "CompilerComponentPlanOracle product control"
    (registryIntegrityProblems <> fixtureIntegrityProblems <> controlProblems)
 where
  primaryCases = exactCasesForLabels [target | (candidate, target) <- compilerComponentPlanSelectorIntents, candidate == selector]
  controlProblems = case primaryCases of
    [exactCase] -> runSelectorProductControl selector exactCase
    _ -> ["product control did not resolve one primary exact case: selector=" <> selector]

runCompilerComponentPlanSelectedOracle :: IO ()
runCompilerComponentPlanSelectedOracle = do
  arguments <- getArgs
  case arguments of
    ["--all"] -> runCompilerComponentPlanOracle
    ["--impacted", selector] -> runCompilerComponentPlanSelectorImpactOracle selector
    ["--unaffected", selector] -> runCompilerComponentPlanSelectorIsolationOracle selector
    ["--control", selector] -> runCompilerComponentPlanSelectorProductControlOracle selector
    [selector] -> runCompilerComponentPlanSelectorOracle selector
    _ -> fail "CompilerComponentPlanOracle selector driver requires a selector or --impacted/--unaffected/--control SELECTOR"

