runSelectorProductControl :: String -> ExactCase -> [String]
runSelectorProductControl selector exactCase
  = case [control | (candidate, control) <- compilerComponentPlanSelectorProductControls, candidate == selector] of
      [SourceCustodyResidueControl] ->
        expectEqual
          (selector <> " assigned fixture preserves independent source-custody residue")
          True
          (sourceCustodyControlFinding `elem` checkFindings actual)
      [PublicCheckNameControl] ->
        expectEqual
          (selector <> " assigned fixture preserves the public check-name envelope")
          "compiler-component-plan-diagnostic"
          (checkName actual)
      controls ->
        [ "selector product-control registry did not resolve exactly once: selector="
            <> selector
            <> "; controls="
            <> show controls
        ]
 where
  actual =
    compilerComponentPlanDiagnostic
      (exactCaseIdentity exactCase)
      [ (wirePath entry, wireMode entry, wireObjectIdentity entry, wireBytes entry)
      | entry <- exactCaseEntries exactCase
      ]

sourceCustodyControlFinding :: Finding
sourceCustodyControlFinding =
  Finding
    "COMPONENT-PLAN-SOURCE-CUSTODY-UNAVAILABLE"
    "compiler-component-plan"
    "an authenticated network-independent source-custody observation is not attached"

compilerComponentPlanSelectorNames :: [String]
compilerComponentPlanSelectorNames = map fst compilerComponentPlanSelectorIntents

registryIntegrityProblems :: [String]
registryIntegrityProblems =
  [ "selector intent cardinality changed: expected=659; observed=" <> show (length compilerComponentPlanSelectorIntents)
  | length compilerComponentPlanSelectorIntents /= 659
  ]
    <> ["duplicate selector intent: " <> selector | selector <- duplicateStrings compilerComponentPlanSelectorNames]
    <> ["duplicate exact-case label: " <> label | label <- duplicateStrings exactCaseLabels]
    <> [ "selector target must occur exactly once: selector="
           <> selector
           <> "; target="
           <> target
           <> "; observed="
           <> show (Map.findWithDefault 0 target exactCaseLabelCounts)
       | (selector, target) <- compilerComponentPlanSelectorIntents
       , Map.findWithDefault 0 target exactCaseLabelCounts /= 1
       ]
    <> [ "unassigned exact-case controls changed: expected="
           <> show expectedUnassignedExactCaseLabels
           <> "; observed="
           <> show unassignedExactCaseLabels
       | unassignedExactCaseLabels /= expectedUnassignedExactCaseLabels
       ]
    <> ["duplicate dependent-case selector: " <> selector | selector <- duplicateStrings dependentSelectors]
    <> [ "dependent-case registry cardinality changed: expected=659; observed="
          <> show (length compilerComponentPlanSelectorDependentCaseLabels)
       | length compilerComponentPlanSelectorDependentCaseLabels /= 659
       ]
    <> [ "dependent-case selector registry is not two-way complete against primary intents"
       | Set.fromList dependentSelectors /= primarySelectorSet
       ]
    <> [ "dependent-case selector is absent from the primary registry: " <> selector
       | selector <- dependentSelectors
       , Set.notMember selector primarySelectorSet
       ]
    <> [ "dependent exact-case label must occur exactly once: selector="
           <> selector
           <> "; exact-case="
           <> label
           <> "; observed="
           <> show (Map.findWithDefault 0 label exactCaseLabelCounts)
       | (selector, labels) <- compilerComponentPlanSelectorDependentCaseLabels
       , label <- labels
       , Map.findWithDefault 0 label exactCaseLabelCounts /= 1
       ]
    <> [ "dependent exact-case labels contain a duplicate: selector=" <> selector <> "; exact-case=" <> label
       | (selector, labels) <- compilerComponentPlanSelectorDependentCaseLabels
       , label <- duplicateStrings labels
       ]
    <> [ "primary and dependent exact-case labels overlap: selector=" <> selector <> "; exact-case=" <> label
       | (selector, labels) <- compilerComponentPlanSelectorDependentCaseLabels
       , label <- labels
       , Map.lookup selector primaryTargetBySelector == Just label
       ]
    <> [ "continuation dependent-case pair cardinality changed: expected="
           <> show compilerComponentPlanContinuationDependentPairCount
           <> "; observed="
           <> show (length compilerComponentPlanContinuationDependentCasePairs)
       | length compilerComponentPlanContinuationDependentCasePairs
           /= compilerComponentPlanContinuationDependentPairCount
       ]
    <> [ "continuation dependent-case selector cardinality changed: expected="
           <> show compilerComponentPlanContinuationDependentSelectorCount
           <> "; observed="
           <> show (Set.size continuationDependentSelectorSet)
       | Set.size continuationDependentSelectorSet
           /= compilerComponentPlanContinuationDependentSelectorCount
       ]
    <> [ "continuation dependent-case registry contains a duplicate pair"
       | Set.size continuationDependentPairSet
           /= length compilerComponentPlanContinuationDependentCasePairs
       ]
    <> [ "continuation dependent-case selector is absent from the primary registry: " <> selector
       | selector <- Set.toAscList continuationDependentSelectorSet
       , Set.notMember selector primarySelectorSet
       ]
    <> [ "continuation dependent exact-case label must occur exactly once: selector="
           <> selector
           <> "; exact-case="
           <> label
           <> "; observed="
           <> show (Map.findWithDefault 0 label exactCaseLabelCounts)
       | (selector, label) <- compilerComponentPlanContinuationDependentCasePairs
       , Map.findWithDefault 0 label exactCaseLabelCounts /= 1
       ]
    <> [ "primary and continuation dependent exact-case labels overlap: selector="
           <> selector
           <> "; exact-case="
           <> label
       | (selector, label) <- compilerComponentPlanContinuationDependentCasePairs
       , Map.lookup selector primaryTargetBySelector == Just label
       ]
    <> [ "base and continuation dependent exact-case labels overlap: selector="
           <> selector
           <> "; exact-case="
           <> label
       | (selector, label) <- compilerComponentPlanContinuationDependentCasePairs
       , Set.member (selector, label) baseDependentPairSet
       ]
    <> [ "continuation dependent exact-case label counts changed: expected="
           <> show compilerComponentPlanContinuationDependentLabelCounts
           <> "; observed="
           <> show continuationDependentObservedLabelCounts
       | continuationDependentObservedLabelCounts
           /= compilerComponentPlanContinuationDependentLabelCounts
       ]
    <> [ "product-control registry cardinality changed: expected=659; observed="
          <> show (length compilerComponentPlanSelectorProductControls)
       | length compilerComponentPlanSelectorProductControls /= 659
       ]
    <> ["duplicate product-control selector: " <> selector | selector <- duplicateStrings productControlSelectors]
    <> [ "product-control selector registry is not two-way complete against primary intents"
       | Set.fromList productControlSelectors /= primarySelectorSet
       ]
    <> [ "source-custody product control must belong only to the check-name selector: observed="
           <> show sourceCustodyControlSelectors
       | sourceCustodyControlSelectors /= ["VALIDATION_COMPILER_PLAN_RESULT_CHECK_NAME_MUTANT"]
       ]
 where
  assignedLabels = Set.fromList (map snd compilerComponentPlanSelectorIntents)
  unassignedExactCaseLabels = filter (`Set.notMember` assignedLabels) exactCaseLabels
  dependentSelectors = map fst compilerComponentPlanSelectorDependentCaseLabels
  productControlSelectors = map fst compilerComponentPlanSelectorProductControls
  sourceCustodyControlSelectors =
    [selector | (selector, SourceCustodyResidueControl) <- compilerComponentPlanSelectorProductControls]
  primarySelectorSet = Set.fromList compilerComponentPlanSelectorNames
  primaryTargetBySelector = Map.fromList compilerComponentPlanSelectorIntents
  continuationDependentPairSet = Set.fromList compilerComponentPlanContinuationDependentCasePairs
  continuationDependentSelectorSet = Set.fromList (map fst compilerComponentPlanContinuationDependentCasePairs)
  continuationDependentObservedLabelCounts =
    Map.toAscList
      (Map.fromListWith (+) [(label, 1 :: Int) | (_, label) <- compilerComponentPlanContinuationDependentCasePairs])
  baseDependentPairSet =
    Set.fromList
      [ (selector, label)
      | (selector, labels) <- compilerComponentPlanSelectorDependentCaseLabels
      , label <- labels
      ]

exactCaseLabels :: [String]
exactCaseLabels = map exactCaseLabel exactCases

exactCaseLabelCounts :: Map.Map String Int
exactCaseLabelCounts = Map.fromListWith (+) [(label, 1) | label <- exactCaseLabels]

