duplicateStrings :: [String] -> [String]
duplicateStrings = Set.toAscList . snd . foldl remember (Set.empty, Set.empty)
 where
  remember (seen, repeated) value
    | Set.member value seen = (seen, Set.insert value repeated)
    | otherwise = (Set.insert value seen, repeated)

data WireEntry = WireEntry
  { wirePath :: FilePath
  , wireMode :: Text
  , wireObjectIdentity :: Text
  , wireBytes :: ByteString
  }

data ProjectionAssignment = ProjectionAssignment
  { projectionAssignmentName :: Text
  , projectionAssignmentKind :: Text
  , projectionAssignmentPath :: FilePath
  , projectionAssignmentMode :: Text
  , projectionAssignmentObjectIdentity :: Text
  , projectionAssignmentModules :: [Text]
  , projectionAssignmentSourceDirectories :: [FilePath]
  , projectionAssignmentLanguage :: Maybe Text
  , projectionAssignmentExtensions :: [Text]
  , projectionAssignmentGhcOptions :: [Text]
  , projectionAssignmentCppOptions :: [Text]
  , projectionAssignmentDependencies :: [Text]
  , projectionAssignmentExtraConfigs :: [ProjectionConfig]
  }

data ProjectionConfig = ProjectionConfig [FilePath] (Maybe Text) [Text] [Text] [Text] [Text]

data ExactCase = ExactCase
  { exactCaseLabel :: String
  , exactCaseIdentity :: Text
  , exactCaseEntries :: [WireEntry]
  , exactCaseExpected :: CheckResult
  , exactCaseIntegrityProblems :: [String]
  }

runExactCase :: ExactCase -> [String]
runExactCase exactCase =
  exactCaseIntegrityProblems exactCase
    <> expectEqual
      (exactCaseLabel exactCase)
      (exactCaseExpected exactCase)
      ( compilerComponentPlanDiagnostic
          (exactCaseIdentity exactCase)
          [ (wirePath entry, wireMode entry, wireObjectIdentity entry, wireBytes entry)
          | entry <- exactCaseEntries exactCase
          ]
      )

