supportedCase :: ExactCase
supportedCase = semanticCase "supported raw input remains an exact refusing diagnostic" supportedEntries ["lib"] [supportedAssignment] []

supportedEntries :: [WireEntry]
supportedEntries = orderedWire [wire "amoebius.cabal" supportedCabal, wire "src/Only.hs" supportedSource]

supportedCabal :: ByteString
supportedCabal =
  packageHeader "Simple"
    <> ByteString8.unlines
      [ "library"
      , "  exposed-modules: Only"
      , "  hs-source-dirs: src"
      , "  default-language: GHC2024"
      ]

supportedSource :: ByteString
supportedSource = "module Only where\nidentity value = value\n"

supportedAssignment :: ProjectionAssignment
supportedAssignment =
  assignment "lib" "main-library" "src/Only.hs" (gitBlobSha1 supportedSource) ["Only"] ["src"] (Just "GHC2024") [] [] [] []

defaultSourceDirectoryCase :: ExactCase
defaultSourceDirectoryCase =
  semanticCase
    "default source directory is projected exactly"
    entries
    ["lib"]
    [assignment "lib" "main-library" "Only.hs" sourceIdentity ["Only"] ["."] (Just "GHC2024") [] [] [] []]
    []
 where
  source = "module Only where\nidentity value = value\n"
  sourceIdentity = gitBlobSha1 source
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "library"
        , "  exposed-modules: Only"
        , "  default-language: GHC2024"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "Only.hs" source]

nestedDefaultSourceDirectoryCase :: ExactCase
nestedDefaultSourceDirectoryCase =
  semanticCase
    "nested default source directory maps to the package root"
    entries
    ["packages/core/lib"]
    [ assignment
        "packages/core/lib"
        "main-library"
        "packages/core/Only.hs"
        sourceIdentity
        ["Only"]
        ["packages/core"]
        (Just "GHC2024")
        []
        []
        []
        []
    ]
    []
 where
  source = "module Only where\nidentity value = value\n"
  sourceIdentity = gitBlobSha1 source
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "library"
        , "  exposed-modules: Only"
        , "  default-language: GHC2024"
        ]
  entries =
    orderedWire
      [ wire "packages/core/core.cabal" declaration
      , wire "packages/core/Only.hs" source
      ]

nestedPackageProjectionCase :: ExactCase
nestedPackageProjectionCase =
