    "nested package root joins every component field exactly"
    entries
    ["packages/core/lib"]
    [ assignment
        "packages/core/lib"
        "main-library"
        "packages/core/src/Only.hs"
        sourceIdentity
        ["Only"]
        ["packages/core/src"]
        (Just "GHC2024")
        []
        []
        []
        []
    ]
    []
 where
  source = "module Only where\nidentity value = value\n"
  sourceIdentity = gitBlobSha1 source
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        ]
  entries =
    orderedWire
      [ wire "packages/core/core.cabal" declaration
      , wire "packages/core/src/Only.hs" source
      ]

executableProjectionCase :: ExactCase
executableProjectionCase =
