    [assignment "exe:tool" "executable" "app/Main.hs" sourceIdentity ["Main"] ["app"] (Just "GHC2024") [] [] [] []]
    []
 where
  source = "module Main where\nmain = pure ()\n"
  sourceIdentity = gitBlobSha1 source
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "app/Main.hs" source]
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "executable tool"
        , "  main-is: Main.hs"
        , "  hs-source-dirs: app"
        , "  default-language: GHC2024"
        ]

