testOtherModuleSingleContributionCase :: ExactCase
testOtherModuleSingleContributionCase =
  semanticCase
    "test BuildInfo other-modules contribute exactly once"
    entries
    ["test:spec"]
    [assignment "test:spec" "test" "test/Spec.hs" sourceIdentity ["Spec"] ["test"] (Just "GHC2024") [] [] [] []]
    [ problem
        "CABAL-DECLARED-MODULE-MISSING"
        "test:spec"
        ("module=M" <> Text.pack (pad3 index) <> "; candidates=[\"test/M" <> Text.pack (pad3 index) <> ".hs\"]")
    | index <- [1 :: Int .. 65]
    ]
 where
  source = "module Spec where\nspec = ()\n"
  sourceIdentity = gitBlobSha1 source
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "test-suite spec"
        , "  type: detailed-0.9"
        , "  test-module: Spec"
        , "  other-modules:"
        , "    " <> ByteString8.unwords ["M" <> ByteString8.pack (pad3 index) | index <- [1 .. 65]]
        , "  hs-source-dirs: test"
        , "  default-language: GHC2024"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "test/Spec.hs" source]

testCodeGeneratorsCase :: ExactCase
testCodeGeneratorsCase =
  semanticCase
    "test code generators remain explicit residue"
    entries
    ["test:spec"]
    [assignment "test:spec" "test" "test/SpecMain.hs" sourceIdentity ["Main"] ["test"] (Just "GHC2024") [] [] [] []]
    [problem "CABAL-BUILD-INFO-FIELD-UNCLOSED" "test:spec" "field=code-generators"]
 where
  source = "module Main where\nmain = pure ()\n"
  sourceIdentity = gitBlobSha1 source
  declaration =
    replaceOnce "cabal-version: 3.0" "cabal-version: 3.14" (packageHeader "Simple")
      <> ByteString8.unlines
        [ "test-suite spec"
        , "  type: exitcode-stdio-1.0"
        , "  main-is: SpecMain.hs"
        , "  hs-source-dirs: test"
        , "  default-language: GHC2024"
        , "  code-generators: hspec-discover"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "test/SpecMain.hs" source]

