absentDescriptionCase :: ExactCase
absentDescriptionCase =
  semanticCase
    "absence of the Cabal declaration is exact"
    [wire "Only.hs" supportedSource]
    []
    []
    [problem "CABAL-DESCRIPTION-ABSENT" "compiler-component-plan" "no bounded immutable .cabal declaration was present"]

projectResidueCase :: ExactCase
projectResidueCase =
  semanticCase
    "cabal.project is never confused with an elaborated plan"
    (orderedWire (wire "cabal.project" "packages: .\n" : supportedEntries))
    ["lib"]
    [supportedAssignment]
    [problem "CABAL-PROJECT-ELABORATION-UNAVAILABLE" "cabal.project" "cabal.project requires an authenticated elaborated install plan"]

extensionlessPathCase :: ExactCase
extensionlessPathCase =
  semanticCase
    "extensionless paths do not become Cabal declarations"
    [wire "README" "documentation\n"]
    []
    []
    [problem "CABAL-DESCRIPTION-ABSENT" "compiler-component-plan" "no bounded immutable .cabal declaration was present"]

parseFailureCase :: ExactCase
parseFailureCase =
  semanticCase
    "malformed Cabal bytes have one exact refusal"
    [wire "amoebius.cabal" "not a Cabal declaration\n"]
    []
    []
    [problem "CABAL-DESCRIPTION-PARSE-FAILED" "amoebius.cabal" "the bounded immutable Cabal bytes did not parse"]

parseBoundaryFalloutCase :: ExactCase
parseBoundaryFalloutCase =
  semanticCase
    "a Cabal parse refusal suppresses secondary ownership analysis"
    ( orderedWire
        [ wire "amoebius.cabal" "not a Cabal declaration\n"
        , wire "src/Only.hs" supportedSource
        ]
    )
    []
    []
    [problem "CABAL-DESCRIPTION-PARSE-FAILED" "amoebius.cabal" "the bounded immutable Cabal bytes did not parse"]

parseWarningCase :: ExactCase
parseWarningCase =
  semanticCase
    "Cabal parser warnings refuse before projection"
    (replaceCabal declaration)
    []
    []
    [ problem
        "CABAL-DESCRIPTION-PARSE-WARNING"
        "amoebius.cabal"
        "the bounded immutable Cabal bytes produced at least one parser warning"
    ]
 where
  declaration = supportedCabal <> "  jspp-options: -foo\n"

parseWarningFalloutCase :: ExactCase
parseWarningFalloutCase =
  semanticCase
    "a Cabal warning refusal suppresses secondary ownership analysis"
    entries
    []
    []
    [ problem
        "CABAL-DESCRIPTION-PARSE-WARNING"
        "amoebius.cabal"
        "the bounded immutable Cabal bytes produced at least one parser warning"
    ]
 where
  declaration = supportedCabal <> "  jspp-options: -foo\n"
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]

buildTypeCase :: ExactCase
buildTypeCase =
  semanticCase
    "non-Simple build type remains residue"
    entries
    ["lib"]
    [supportedAssignment]
    [problem "CABAL-BUILD-TYPE-UNSUPPORTED" "amoebius.cabal" "observed=Configure; admitted=Simple"]
 where
  entries = replaceCabal (replaceOnce "build-type: Simple" "build-type: Configure" supportedCabal)

customSetupCase :: ExactCase
customSetupCase =
  semanticCase
    "custom Setup is distinct from build-type residue"
    entries
    ["lib"]
    [supportedAssignment]
    [ problem "CABAL-BUILD-TYPE-UNSUPPORTED" "amoebius.cabal" "observed=Custom; admitted=Simple"
    , problem "CABAL-CUSTOM-SETUP-UNSUPPORTED" "amoebius.cabal" "custom Setup execution is outside the restricted component diagnostic"
    ]
 where
  declaration =
    replaceOnce "build-type: Simple" "build-type: Custom" (packageHeader "Simple")
      <> ByteString8.unlines
        [ "custom-setup"
        , "  setup-depends: base"
        , "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        ]
  entries = replaceCabal declaration

packageFieldCase :: ExactCase
packageFieldCase =
  semanticCase
    "package-level behavioral data is explicit"
    (replaceCabal (packageHeader "Simple" <> "data-files: data/input.txt\n" <> componentBody))
    ["lib"]
    [supportedAssignment]
    [problem "CABAL-PACKAGE-FIELD-UNCLOSED" "amoebius.cabal" "field=data-files"]

conditionalCase :: ExactCase
conditionalCase =
  semanticCase
    "a Cabal condition is complete ordered residue"
    (replaceCabal declaration)
    ["lib"]
    [supportedAssignment]
    [problem "CABAL-CONDITIONAL-CONFIGURATION-UNCLOSED" "lib" "condition=Var (PackageFlag (FlagName \"variant\"))"]
 where
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "flag variant"
        , "  default: False"
        , "  manual: True"
        , "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        , "  if flag(variant)"
        , "    buildable: True"
        ]

nestedConditionalCase :: ExactCase
nestedConditionalCase =
  semanticCase
    "true and false nested condition recursion is exact"
    [wire "amoebius.cabal" declaration]
    ["lib"]
    []
    [ innerProblem
    , innerProblem
    , problem
        "CABAL-CONDITIONAL-CONFIGURATION-UNCLOSED"
        "lib"
        "condition=Var (PackageFlag (FlagName \"outer\"))"
    ]
 where
  innerProblem =
    problem
      "CABAL-CONDITIONAL-CONFIGURATION-UNCLOSED"
      "lib"
      "condition=Var (PackageFlag (FlagName \"inner\"))"
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "flag outer"
        , "  default: False"
        , "  manual: True"
        , "flag inner"
        , "  default: False"
        , "  manual: True"
        , "library"
        , "  default-language: GHC2024"
        , "  if flag(outer)"
        , "    if flag(inner)"
        , "      buildable: True"
        , "    else"
        , "      buildable: True"
        , "  else"
        , "    if flag(inner)"
        , "      buildable: True"
        , "    else"
        , "      buildable: True"
        ]

foreignLibraryCase :: ExactCase
foreignLibraryCase =
  semanticCase
    "foreign libraries remain exact residue"
    [wire "amoebius.cabal" declaration]
    []
    []
    [problem "CABAL-FOREIGN-LIBRARY-UNSUPPORTED" "amoebius.cabal" "name=ffi"]
 where
