    ["lib"]
    [supportedAssignment]
    [problem "CABAL-AUTOGEN-MODULE-UNSUPPORTED" "lib" "module=Generated"]

declaredModuleMissingCase :: ExactCase
declaredModuleMissingCase =
  semanticCase
    "a missing declared module is exact"
    [wire "amoebius.cabal" supportedCabal]
    ["lib"]
    []
    [problem "CABAL-DECLARED-MODULE-MISSING" "lib" "module=Only; candidates=[\"src/Only.hs\"]"]

declaredModuleAmbiguousCase :: ExactCase
declaredModuleAmbiguousCase =
  semanticCase
    "two exact candidates are not sorted into acceptance"
    entries
    ["lib"]
    [ assignment "lib" "main-library" "alt/Only.hs" altIdentity ["Only"] ["src", "alt"] (Just "GHC2024") [] [] [] []
    , assignment "lib" "main-library" "src/Only.hs" srcIdentity ["Only"] ["src", "alt"] (Just "GHC2024") [] [] [] []
    ]
    [problem "CABAL-DECLARED-MODULE-AMBIGUOUS" "lib" "module=Only; candidates=[\"alt/Only.hs\",\"src/Only.hs\"]"]
 where
  declaration = replaceOnce "hs-source-dirs: src" "hs-source-dirs: src, alt" supportedCabal
  altBytes = "module Only where\nalt = True\n"
  srcIdentity = gitBlobSha1 supportedSource
  altIdentity = gitBlobSha1 altBytes
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "alt/Only.hs" altBytes, wire "src/Only.hs" supportedSource]

mainModuleMissingCase :: ExactCase
mainModuleMissingCase =
  semanticCase
    "a missing main-is path is exact"
    [wire "amoebius.cabal" executableCabal]
    ["exe:tool"]
    []
    [problem "CABAL-MAIN-MODULE-MISSING" "exe:tool" "main=Main.hs; candidates=[\"app/Main.hs\"]"]

mainModuleAmbiguousCase :: ExactCase
mainModuleAmbiguousCase =
  semanticCase
    "two main-is candidates remain ambiguous"
    entries
    ["exe:tool"]
    [ assignment "exe:tool" "executable" "alt/Main.hs" altIdentity ["Main"] ["app", "alt"] (Just "GHC2024") [] [] [] []
    , assignment "exe:tool" "executable" "app/Main.hs" appIdentity ["Main"] ["app", "alt"] (Just "GHC2024") [] [] [] []
    ]
    [problem "CABAL-MAIN-MODULE-AMBIGUOUS" "exe:tool" "main=Main.hs; candidates=[\"alt/Main.hs\",\"app/Main.hs\"]"]
 where
  declaration = replaceOnce "hs-source-dirs: app" "hs-source-dirs: app, alt" executableCabal
  appBytes = "module Main where\nmain = pure ()\n"
  altBytes = "module Main where\nmain = pure True\n"
  appIdentity = gitBlobSha1 appBytes
  altIdentity = gitBlobSha1 altBytes
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "alt/Main.hs" altBytes, wire "app/Main.hs" appBytes]

expectationConflictCase :: ExactCase
expectationConflictCase =
  semanticCase
    "one path cannot satisfy two declared module identities"
    entries
    ["exe:tool"]
    [assignment "exe:tool" "executable" "src/Foo.hs" objectIdentity ["Foo", "Main"] ["src"] (Just "GHC2024") [] [] [] []]
    [problem "CABAL-DECLARED-MODULE-EXPECTATION-CONFLICT" "src/Foo.hs" "component=exe:tool; modules=[\"Foo\",\"Main\"]"]
 where
  source = "module Foo where\nmain = pure ()\n"
  objectIdentity = gitBlobSha1 source
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "executable tool"
        , "  main-is: Foo.hs"
        , "  other-modules: Foo"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Foo.hs" source]

unsafeDeclaredPathCase :: ExactCase
unsafeDeclaredPathCase =
  semanticCase
    "Cabal paths use exact POSIX repository grammar"
    entries
    ["lib"]
    []
    [ problem "CABAL-DECLARED-MODULE-MISSING" "lib" "module=Only; candidates=[\"../src/Only.hs\"]"
    , problem "CABAL-DECLARED-PATH-UNSAFE" "../src" "component=lib; required=safe relative POSIX repository path"
    , problem "CABAL-HASKELL-SUBJECT-UNOWNED" "src/Only.hs" "the exact Haskell subject has no Cabal component assignment"
    ]
 where
  declaration = replaceOnce "hs-source-dirs: src" "hs-source-dirs: ../src" supportedCabal
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]

unsafeMainPathCase :: ExactCase
unsafeMainPathCase =
  semanticCase
    "unsafe main path contributes independently"
    entries
    ["exe:tool"]
    []
    [ problem "CABAL-MAIN-MODULE-MISSING" "exe:tool" "main=../Main.hs; candidates=[\"app/../Main.hs\"]"
    , problem "CABAL-DECLARED-PATH-UNSAFE" "../Main.hs" "component=exe:tool; required=safe relative POSIX repository path"
    , problem "CABAL-HASKELL-SUBJECT-UNOWNED" "app/Main.hs" "the exact Haskell subject has no Cabal component assignment"
    ]
 where
  source = "module Main where\nmain = pure ()\n"
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "executable tool"
        , "  main-is: ../Main.hs"
        , "  hs-source-dirs: app"
        , "  default-language: GHC2024"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "app/Main.hs" source]

unownedSubjectCase :: ExactCase
unownedSubjectCase =
  semanticCase
    "an unlisted Haskell subject is exact residue"
    entries
    ["lib"]
    [supportedAssignment]
    [problem "CABAL-HASKELL-SUBJECT-UNOWNED" "src/Orphan.hs" "the exact Haskell subject has no Cabal component assignment"]
 where
  entries = orderedWire (wire "src/Orphan.hs" "module Orphan where\n" : supportedEntries)

ghcOptionCase, cppOptionCase, languageCase, extensionCase, otherExtensionCase, legacyExtensionCase, hazardousExtensionCase, dependencyCase, buildInfoCase :: ExactCase
ghcOptionCase = configuredCase "GHC option residue is exact" "  ghc-options: -Wall\n" ["-Wall"] [] [] (Just "GHC2024") [] [] [problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=-Wall"]
cppOptionCase = configuredCase "CPP option residue is exact" "  cpp-options: -DVALUE\n" [] ["-DVALUE"] [] (Just "GHC2024") [] [] [problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=-DVALUE"]
languageCase = configuredCase "language drift is exact" "" [] [] [] (Just "Haskell2010") [] [] [problem "CABAL-COMPILER-LANGUAGE-UNCLOSED" "lib" "language=Just \"Haskell2010\""]
extensionCase = configuredCase "extension residue is exact" "  default-extensions: LambdaCase\n" [] [] ["LambdaCase"] (Just "GHC2024") [] [] [problem "CABAL-COMPILER-EXTENSIONS-UNCLOSED" "lib" "extensions=[\"LambdaCase\"]"]
otherExtensionCase = configuredCase "other-extensions source contribution is exact" "  other-extensions: LambdaCase\n" [] [] ["LambdaCase"] (Just "GHC2024") [] [] [problem "CABAL-COMPILER-EXTENSIONS-UNCLOSED" "lib" "extensions=[\"LambdaCase\"]"]
legacyExtensionCase =
  semanticCase
    "legacy extensions remain bounded compiler configuration"
    entries
    ["lib"]
    [assignment "lib" "main-library" "src/Only.hs" (gitBlobSha1 supportedSource) ["Only"] ["src"] (Just "Haskell2010") ["CPP"] [] [] []]
    [ problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=CPP"
    , problem "CABAL-COMPILER-LANGUAGE-UNCLOSED" "lib" "language=Just \"Haskell2010\""
    , problem "CABAL-COMPILER-EXTENSIONS-UNCLOSED" "lib" "extensions=[\"CPP\"]"
    ]
 where
  declaration = legacyPackageHeader <> legacyLibraryBody <> "  extensions: CPP\n"
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]
hazardousExtensionCase = configuredCase "hazardous extension has both exact refusals" "  default-extensions: CPP\n" [] [] ["CPP"] (Just "GHC2024") [] [] [problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=CPP", problem "CABAL-COMPILER-EXTENSIONS-UNCLOSED" "lib" "extensions=[\"CPP\"]"]
dependencyCase = configuredCase "dependency environment residue is exact" "  build-depends: base\n" [] [] [] (Just "GHC2024") ["base"] [] [problem "CABAL-COMPILER-DEPENDENCIES-UNCLOSED" "lib" "dependencies=[\"base\"]"]
buildInfoCase = configuredCase "unsupported BuildInfo field is exact" "  c-sources: cbits/legacy.c\n" [] [] [] (Just "GHC2024") [] ["c-sources"] [problem "CABAL-BUILD-INFO-FIELD-UNCLOSED" "lib" "field=c-sources"]

legacyBuildToolsCase :: ExactCase
legacyBuildToolsCase =
  semanticCase
    "legacy build tools remain explicit residue"
    entries
    ["lib"]
    [assignment "lib" "main-library" "src/Only.hs" (gitBlobSha1 supportedSource) ["Only"] ["src"] (Just "Haskell2010") [] [] [] []]
    [ problem "CABAL-COMPILER-LANGUAGE-UNCLOSED" "lib" "language=Just \"Haskell2010\""
    , problem "CABAL-BUILD-INFO-FIELD-UNCLOSED" "lib" "field=build-tools"
    ]
 where
  declaration = legacyPackageHeader <> legacyLibraryBody <> "  build-tools: happy\n"
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]

legacyPackageHeader :: ByteString
legacyPackageHeader =
  ByteString8.unlines
    [ "name: component-plan-oracle"
    , "version: 0.1.0.0"
    , "cabal-version: >= 1.10"
    , "build-type: Simple"
    ]

legacyLibraryBody :: ByteString
legacyLibraryBody =
