reexportCase :: ExactCase
reexportCase =
  semanticCase
    "module reexports and their dependency environment are both exact"
    entries
    ["lib"]
    [assignment "lib" "main-library" "src/Only.hs" (gitBlobSha1 supportedSource) ["Only"] ["src"] (Just "GHC2024") [] [] [] ["base"]]
    [ problem "CABAL-COMPILER-DEPENDENCIES-UNCLOSED" "lib" "dependencies=[\"base\"]"
    , problem "CABAL-MODULE-REEXPORT-UNSUPPORTED" "lib" "module=base:Prelude"
    ]
 where
  declaration = supportedCabal <> "  build-depends: base\n  reexported-modules: base:Prelude as Prelude\n"
  entries = replaceCabal declaration

configurationDifferenceCase :: ExactCase
configurationDifferenceCase =
  semanticCase
    "conditional configurations cannot collapse"
    entries
    ["lib"]
    [baseAssignment {projectionAssignmentExtraConfigs = [ProjectionConfig ["src"] (Just "GHC2024") [] ["-Wall"] [] []]}]
    [ problem "CABAL-CONDITIONAL-CONFIGURATION-UNCLOSED" "lib" "condition=Var (PackageFlag (FlagName \"variant\"))"
    , problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=-Wall"
    , problem
        "CABAL-COMPONENT-CONFIGURATIONS-DIFFER"
        "lib"
        "configurations=[{source-dirs=[\"src\"]; default-language=Just \"GHC2024\"; extensions=[]; ghc-options=[]; cpp-options=[]; dependencies=[]},{source-dirs=[\"src\"]; default-language=Just \"GHC2024\"; extensions=[]; ghc-options=[\"-Wall\"]; cpp-options=[]; dependencies=[]}]"
    ]
 where
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "flag variant"
        , "  default: False"
        , "  manual: True"
        , "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        , "  if flag(variant)"
        , "    ghc-options: -Wall"
        ]
  entries = replaceCabal declaration
  baseAssignment = supportedAssignment

