    , problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=-DVALUE"
    , problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" "option=-Wall"
    , problem
        "CABAL-COMPONENT-CONFIGURATIONS-DIFFER"
        "lib"
        "configurations=[{source-dirs=[\"src\"]; default-language=Just \"GHC2024\"; extensions=[]; ghc-options=[]; cpp-options=[]; dependencies=[]},{source-dirs=[\"src\"]; default-language=Just \"GHC2024\"; extensions=[]; ghc-options=[]; cpp-options=[\"-DVALUE\"]; dependencies=[]},{source-dirs=[\"src\"]; default-language=Just \"GHC2024\"; extensions=[]; ghc-options=[\"-Wall\"]; cpp-options=[]; dependencies=[]}]"
    ]
 where
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "flag variant"
        , "  default: False"
        , "  manual: True"
        , "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: GHC2024"
        , "  if flag(variant)"
        , "    ghc-options: -Wall"
        , "  else"
        , "    cpp-options: -DVALUE"
        ]
  entries = replaceCabal declaration
  baseAssignment = supportedAssignment

