hazardousExtensionAlternativesCase :: ExactCase
hazardousExtensionAlternativesCase =
  configuredCase
    "all hazardous extension alternatives are exact"
    ("  default-extensions: " <> ByteString8.unwords (map TextEncoding.encodeUtf8 extensions) <> "\n")
    []
    []
    extensions
    (Just "GHC2024")
    []
    []
    ( map (problem "CABAL-COMPILER-OPTION-UNCLOSED" "lib" . ("option=" <>)) extensions
        <> [problem "CABAL-COMPILER-EXTENSIONS-UNCLOSED" "lib" ("extensions=" <> Text.pack (show extensions))]
    )
 where
  extensions =
    [ "CApiFFI"
    , "CPP"
    , "ForeignFunctionInterface"
    , "JavaScriptFFI"
    , "QuasiQuotes"
    , "TemplateHaskell"
    , "TemplateHaskellQuotes"
    , "UnliftedFFITypes"
    ]

allowedPathAlphabetCase :: ExactCase
allowedPathAlphabetCase =
  absentEntriesCase
    "every admitted path alphabet alternative is exact"
    [wire "aA0._+@/b=c-d" "alphabet"]

rawGrammarInventoryGateCase :: ExactCase
rawGrammarInventoryGateCase =
  earlyLimitCase
    "grammar refusal suppresses inventory-order analysis"
    [ (wire "b.txt" "b") {wireMode = "100664"}
    , wire "a.txt" "a"
    ]
    "2"
    "2"
    [problem "COMPONENT-PLAN-MODE-MALFORMED" "b.txt" "observed=100664; admitted=100644|100755|120000"]

configuredCase
  :: String -> ByteString -> [Text] -> [Text] -> [Text] -> Maybe Text -> [Text] -> [Text] -> [Finding] -> ExactCase
configuredCase label extra ghcOptions cppOptions extensions languageValue dependencies _unsupported expectedProblems =
  semanticCase label entries ["lib"] [projectedAssignment] expectedProblems
 where
  languageBytes = maybe "" TextEncoding.encodeUtf8 languageValue
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "library"
        , "  exposed-modules: Only"
        , "  hs-source-dirs: src"
        , "  default-language: " <> languageBytes
        ]
      <> extra
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]
  projectedAssignment = assignment "lib" "main-library" "src/Only.hs" (gitBlobSha1 supportedSource) ["Only"] ["src"] languageValue extensions ghcOptions cppOptions dependencies

multipleComponentCase :: ExactCase
multipleComponentCase =
  semanticCase
    "multiple components remain exact residue"
    entries
    ["exe:tool", "lib"]
    [ assignment "exe:tool" "executable" "app/Main.hs" mainIdentity ["Main"] ["app"] (Just "GHC2024") [] [] [] []
    , supportedAssignment
    ]
    [problem "CABAL-MULTIPLE-COMPONENTS-UNCLOSED" "compiler-component-plan" "components=[\"exe:tool\",\"lib\"]"]
 where
  mainBytes = "module Main where\nmain = pure ()\n"
  mainIdentity = gitBlobSha1 mainBytes
  declaration =
    supportedCabal
      <> ByteString8.unlines
        [ "executable tool"
        , "  main-is: Main.hs"
        , "  hs-source-dirs: app"
        , "  default-language: GHC2024"
        ]
  entries = orderedWire [wire "amoebius.cabal" declaration, wire "app/Main.hs" mainBytes, wire "src/Only.hs" supportedSource]

snapshotIdentityMalformedCase :: ExactCase
snapshotIdentityMalformedCase =
  rawFailureCase
    "snapshot identity grammar is exact"
    (Text.replicate 63 "a" <> "g")
    supportedEntries
    (decimalText (length supportedEntries))
    (decimalText (aggregateBytes supportedEntries))
    (inventorySha256 supportedEntries)
    [problem "COMPONENT-PLAN-SNAPSHOT-IDENTITY-MALFORMED" "compiler-component-plan" ("observed=" <> Text.replicate 63 "a" <> "g; required=64 lowercase hexadecimal")]

