objectLength39Case = earlyLimitCase "39-byte object identity is refused independently" [WireEntry "object.txt" "100644" (Text.replicate 39 "a") "object"] "1" "6" [problem "COMPONENT-PLAN-OBJECT-IDENTITY-MALFORMED" "object.txt" ("observed=" <> Text.replicate 39 "a" <> "; admitted=40-or-64 lowercase hexadecimal")]
objectLength41Case = earlyLimitCase "41-byte object identity is refused independently" [WireEntry "object.txt" "100644" (Text.replicate 41 "a") "object"] "1" "6" [problem "COMPONENT-PLAN-OBJECT-IDENTITY-MALFORMED" "object.txt" ("observed=" <> Text.replicate 41 "a" <> "; admitted=40-or-64 lowercase hexadecimal")]
objectLength63Case = earlyLimitCase "63-byte object identity is refused independently" [WireEntry "object.txt" "100644" (Text.replicate 63 "a") "object"] "1" "6" [problem "COMPONENT-PLAN-OBJECT-IDENTITY-MALFORMED" "object.txt" ("observed=" <> Text.replicate 63 "a" <> "; admitted=40-or-64 lowercase hexadecimal")]
objectUppercaseCase = earlyLimitCase "uppercase object identity is refused independently" [WireEntry "object.txt" "100644" (Text.replicate 39 "a" <> "A") "object"] "1" "6" [problem "COMPONENT-PLAN-OBJECT-IDENTITY-MALFORMED" "object.txt" ("observed=" <> Text.replicate 39 "a" <> "A; admitted=40-or-64 lowercase hexadecimal")]
objectContentCase = earlyLimitCase "object identity binds exact blob content" [WireEntry "object.txt" "100644" (Text.replicate 40 "0") "object"] "1" "6" [problem "COMPONENT-PLAN-OBJECT-IDENTITY-MISMATCH" "object.txt" ("expected=" <> gitBlobSha1 "object" <> "; observed=" <> Text.replicate 40 "0")]
