safeProblemPathFallbackCase :: ExactCase
safeProblemPathFallbackCase =
  rawFailureCase
    "over-limit problem paths use one bounded fallback"
    zeroIdentity
    [wire overLimitPath overLimitBlob]
    "1"
    "65537"
    "unavailable"
    [ limitProblem "COMPONENT-PLAN-PATH-BYTE-LIMIT" "entry-1" 240 241
    , limitProblem "COMPONENT-PLAN-BLOB-BYTE-LIMIT" "<entry-1-path-over-limit>" 65536 65537
    ]
 where
  overLimitPath = replicate 241 'a'
  overLimitBlob = ByteString.replicate 65537 97

emptyPathCase, absolutePathCase, nulPathCase, backslashPathCase, emptySegmentCase, dotSegmentCase, parentSegmentCase, unsafeCharacterCase :: ExactCase
emptyPathCase = earlyLimitCase "empty path is one exact grammar refusal" [wire "" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-EMPTY" "entry-1" "repository paths must contain at least one byte"]
absolutePathCase = earlyLimitCase "absolute path is one exact grammar refusal" [wire "/a" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-ABSOLUTE" "/a" "repository paths must be relative POSIX paths"]
nulPathCase = earlyLimitCase "NUL path is one exact grammar refusal" [wire "a\0b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-NUL" "a\0b" "repository paths must not contain NUL"]
backslashPathCase = earlyLimitCase "backslash path is one exact grammar refusal" [wire "a\\b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-BACKSLASH" "a\\b" "backslash is not a POSIX repository-path separator"]
emptySegmentCase = earlyLimitCase "empty segment is one exact grammar refusal" [wire "a//b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-EMPTY-SEGMENT" "a//b" "repository paths must not contain empty segments"]
dotSegmentCase = earlyLimitCase "dot segment is one exact grammar refusal" [wire "a/./b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-DOT-SEGMENT" "a/./b" "repository paths must not contain dot segments"]
parentSegmentCase = earlyLimitCase "parent segment is one exact grammar refusal" [wire "a/../b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-PARENT-SEGMENT" "a/../b" "repository paths must not contain parent segments"]
unsafeCharacterCase = earlyLimitCase "unsafe character does not enter POSIX grammar" [wire "a:b" ""] "1" "0" [problem "COMPONENT-PLAN-PATH-CHARACTER-UNSAFE" "a:b" "repository paths admit only ASCII alphanumeric and ._+@/=- characters"]

duplicatePathCase, entryOrderCase :: ExactCase
duplicatePathCase = earlyLimitCase "duplicate paths are exact" [wire "same.txt" "a", wire "same.txt" "a"] "2" "2" [problem "COMPONENT-PLAN-DUPLICATE-PATH" "same.txt" "the raw inventory contains the path more than once"]
entryOrderCase = earlyLimitCase "input order must already be canonical" [wire "b.txt" "", wire "a.txt" ""] "2" "0" [problem "COMPONENT-PLAN-ENTRY-ORDER" "compiler-component-plan" "observed=[\"b.txt\",\"a.txt\"]; required=ascending POSIX byte order"]

