assignmentExpansionLimitCase :: ExactCase
assignmentExpansionLimitCase =
  semanticCase
    "candidate expansion is bounded before assignment maps and sorting"
    entries
    ["lib"]
    []
    [limitProblem "COMPONENT-PLAN-ASSIGNMENT-LIMIT" "compiler-component-plan" 64 65]
 where
  modules = ["M001", "M002", "M003"]
  directories = ["d" <> pad3 index | index <- [1 .. 22]]
  declaration =
    packageHeader "Simple"
      <> ByteString8.unlines
        [ "library"
        , "  exposed-modules: " <> ByteString8.unwords (map ByteString8.pack modules)
        , "  hs-source-dirs: " <> ByteString8.unwords (map ByteString8.pack directories)
        , "  default-language: GHC2024"
        ]
  entries =
    orderedWire
      ( wire "amoebius.cabal" declaration
          : [ wire (directory <> "/" <> moduleName <> ".hs") (ByteString8.pack ("module " <> moduleName <> " where\n"))
            | directory <- directories
            , moduleName <- modules
            ]
      )

