problemLimitMaxCase, problemLimitMaxPlusOneCase, resultLimitMaxCase, resultLimitMaxPlusOneCase :: ExactCase
problemLimitMaxCase = unownedCountCase "problem max remains bounded before rendering" 66 resultLimitFinding
problemLimitMaxPlusOneCase =
  semanticCase
    "problem max+1 is replaced by one exact refusal"
    (unownedEntries 67)
    ["lib"]
    []
    [limitProblem "COMPONENT-PLAN-PROBLEM-LIMIT" "compiler-component-plan" 66 67]
resultLimitMaxCase = unownedCountCase "result-finding max is admitted" 65 (map unownedProblem [1 .. 65] <> mandatoryFindings)
resultLimitMaxPlusOneCase = unownedCountCase "result-finding max+1 is replaced before rendering" 66 resultLimitFinding

resultLimitFinding :: [Finding]
resultLimitFinding =
  mandatoryFindings
    <> [ problem
           "COMPONENT-PLAN-RESULT-FINDING-LIMIT"
           "compiler-component-plan"
           "limit=69; observed-at-least=70; the oversized result was replaced before rendering"
       ]

unownedCountCase :: String -> Int -> [Finding] -> ExactCase
unownedCountCase label count expectedRendered =
  semanticCaseWithRenderedFindings label (unownedEntries count) ["lib"] [] (map unownedProblem [1 .. count]) expectedRendered

unownedEntries :: Int -> [WireEntry]
unownedEntries count =
  orderedWire
    ( wire "amoebius.cabal" emptyLibraryCabal
        : [wire ("orphan/O" <> pad3 index <> ".hs") "module Orphan where\n" | index <- [1 .. count]]
    )

unownedProblem :: Int -> Finding
unownedProblem index = problem "CABAL-HASKELL-SUBJECT-UNOWNED" ("orphan/O" <> pad3 index <> ".hs") "the exact Haskell subject has no Cabal component assignment"

emptyLibraryCabal :: ByteString
emptyLibraryCabal = packageHeader "Simple" <> ByteString8.unlines ["library", "  default-language: GHC2024"]

invalidStructuralMaxCase :: String -> ByteString -> ExactCase
invalidStructuralMaxCase label structuralBytes =
  semanticCase label [wire "amoebius.cabal" ("!\n" <> structuralBytes)] [] [] [problem "CABAL-DESCRIPTION-PARSE-FAILED" "amoebius.cabal" "the bounded immutable Cabal bytes did not parse"]

structuralLimitCase :: String -> ByteString -> Finding -> ExactCase
structuralLimitCase label structuralBytes expectedProblem =
  semanticCase label [wire "amoebius.cabal" ("!\n" <> structuralBytes)] [] [] [expectedProblem]

semanticCase :: String -> [WireEntry] -> [Text] -> [ProjectionAssignment] -> [Finding] -> ExactCase
semanticCase label entries components assignments problems =
  semanticCaseWithRenderedFindings label entries components assignments problems (problems <> mandatoryFindings)

semanticCaseWithRenderedFindings
  :: String -> [WireEntry] -> [Text] -> [ProjectionAssignment] -> [Finding] -> [Finding] -> ExactCase
semanticCaseWithRenderedFindings label rawEntries components assignments problems renderedFindings =
  ExactCase
    { exactCaseLabel = label
    , exactCaseIdentity = computedIdentity
    , exactCaseEntries = entries
    , exactCaseExpected = expectedResult literals renderedFindings
    , exactCaseIntegrityProblems =
        observationLiteralIntegrity
          label
          literals
          (decimalText (length entries))
          (decimalText (aggregateBytes entries))
          computedIdentity
          (decimalText (length components))
          (decimalText (length assignments))
          (decimalText (length problems))
          (projectionSha256 computedIdentity components assignments problems)
    }
 where
  entries = orderedWire rawEntries
  computedIdentity = inventorySha256 entries
  literals = observationLiteralsFor label

absentEntriesCase :: String -> [WireEntry] -> ExactCase
absentEntriesCase label entries =
  semanticCase label (orderedWire entries) [] [] [problem "CABAL-DESCRIPTION-ABSENT" "compiler-component-plan" "no bounded immutable .cabal declaration was present"]

rawFailureCase :: String -> Text -> [WireEntry] -> Text -> Text -> Text -> [Finding] -> ExactCase
rawFailureCase label claimedIdentity entries entryCount aggregateValue inventoryDigest problems =
  ExactCase
    { exactCaseLabel = label
    , exactCaseIdentity = claimedIdentity
    , exactCaseEntries = entries
    , exactCaseExpected = expectedResult literals (problems <> mandatoryFindings)
    , exactCaseIntegrityProblems =
        observationLiteralIntegrity
          label
          literals
          entryCount
          aggregateValue
          inventoryDigest
          "0"
          "0"
          (decimalText (length problems))
          (projectionSha256 "unavailable" [] [] problems)
    }
 where
  literals = observationLiteralsFor label

earlyLimitCase :: String -> [WireEntry] -> Text -> Text -> [Finding] -> ExactCase
earlyLimitCase label entries entryCount aggregateValue =
  rawFailureCase label zeroIdentity entries entryCount aggregateValue "unavailable"

data ObservationLiterals = ObservationLiterals
  { literalEntryCount :: Text
  , literalAggregateValue :: Text
  , literalInventoryDigest :: Text
  , literalComponentCount :: Text
  , literalAssignmentCount :: Text
  , literalProblemCount :: Text
  , literalProjectionDigest :: Text
  , literalDiagnosticStatus :: Text
  }

expectedResult :: ObservationLiterals -> [Finding] -> CheckResult
expectedResult literals renderedFindings =
  CheckResult
    { checkName = "compiler-component-plan-diagnostic"
    , checkObservations =
        [ Observation "component-plan.input.entry-count" (literalEntryCount literals)
        , Observation "component-plan.input.aggregate-blob-bytes" (literalAggregateValue literals)
        , Observation "component-plan.input.inventory-sha256" (literalInventoryDigest literals)
        , Observation "component-plan.derived.component-count" (literalComponentCount literals)
        , Observation "component-plan.derived.assignment-count" (literalAssignmentCount literals)
        , Observation "component-plan.derived.problem-count" (literalProblemCount literals)
        , Observation "component-plan.derived.projection-sha256" (literalProjectionDigest literals)
        , Observation "component-plan.diagnostic-status" (literalDiagnosticStatus literals)
        ]
    , checkFindings = renderedFindings
    }

observationLiteralIntegrity
  :: String
  -> ObservationLiterals
  -> Text
  -> Text
  -> Text
  -> Text
  -> Text
  -> Text
  -> Text
  -> [String]
observationLiteralIntegrity label literals entryCount aggregateValue inventoryDigest componentCount assignmentCount problemCount projectionDigest =
  concat
    [ expectEqual (label <> " literal entry count") (literalEntryCount literals) entryCount
    , expectEqual (label <> " literal aggregate bytes") (literalAggregateValue literals) aggregateValue
    , expectEqual (label <> " literal inventory digest") (literalInventoryDigest literals) inventoryDigest
    , expectEqual (label <> " literal component count") (literalComponentCount literals) componentCount
    , expectEqual (label <> " literal assignment count") (literalAssignmentCount literals) assignmentCount
    , expectEqual (label <> " literal problem count") (literalProblemCount literals) problemCount
    , expectEqual (label <> " literal projection digest") (literalProjectionDigest literals) projectionDigest
    , expectEqual (label <> " literal diagnostic status") (literalDiagnosticStatus literals) "refused"
    ]

-- Frozen expectations are deliberately separate from fixture recomputation.
-- Changing a fixture can therefore only create an integrity failure; it cannot
-- silently rewrite the CheckResult that the production subject must match.
observationLiteralsFor :: String -> ObservationLiterals
observationLiteralsFor label = case label of
    "supported raw input remains an exact refusing diagnostic" -> ObservationLiterals "2" "206" "cca4095c47a7bb78b700ba1aa1815d2f165ba666bfc023e77de39d732dd85966" "1" "1" "0" "626bbd8431e79272b10513c4d7d166b24dd341a5b920f61ee7d6d8429d19a384" "refused"
