mandatoryFindings :: [Finding]
mandatoryFindings =
  [ problem "COMPONENT-PLAN-DIAGNOSTIC-ONLY" "compiler-component-plan" "raw caller input can produce diagnostics only; it cannot mint component-plan evidence"
  , problem "COMPONENT-PLAN-SOURCE-CUSTODY-UNAVAILABLE" "compiler-component-plan" "an authenticated network-independent source-custody observation is not attached"
  , problem "COMPONENT-PLAN-CABAL-ELABORATION-UNAVAILABLE" "compiler-component-plan" "Cabal project and conditional-unit elaboration remains outside this restricted parser"
  , problem "COMPONENT-PLAN-COMPILER-EXECUTION-UNAVAILABLE" "compiler-component-plan" "the linked compiler has not parsed, renamed, and typechecked the exact assignments"
  ]

problem :: Text -> FilePath -> Text -> Finding
problem = Finding

limitProblem :: Text -> FilePath -> Int -> Int -> Finding
limitProblem code subject limit observed =
  problem code subject ("limit=" <> decimalText limit <> "; observed-at-least=" <> decimalText observed)

assignment
  :: Text -> Text -> FilePath -> Text -> [Text] -> [FilePath] -> Maybe Text -> [Text] -> [Text] -> [Text] -> [Text] -> ProjectionAssignment
assignment name kind path objectIdentity modules sourceDirectories languageValue extensions ghcOptions cppOptions dependencies =
  ProjectionAssignment
    name
    kind
    path
    "100644"
    objectIdentity
    modules
    sourceDirectories
    languageValue
    extensions
    ghcOptions
    cppOptions
    dependencies
    []

wire :: FilePath -> ByteString -> WireEntry
wire path bytes = WireEntry path "100644" (gitBlobSha1 bytes) bytes

wireWithMode :: FilePath -> Text -> ByteString -> WireEntry
wireWithMode path mode bytes = WireEntry path mode (gitBlobSha1 bytes) bytes

wireSha256 :: FilePath -> ByteString -> WireEntry
wireSha256 path bytes = WireEntry path "100644" (gitBlobSha256 bytes) bytes

orderedWire :: [WireEntry] -> [WireEntry]
orderedWire = sortOn wirePath

replaceCabal :: ByteString -> [WireEntry]
replaceCabal declaration = orderedWire [wire "amoebius.cabal" declaration, wire "src/Only.hs" supportedSource]

replaceOnce :: ByteString -> ByteString -> ByteString -> ByteString
replaceOnce needle replacement input =
  case ByteString.breakSubstring needle input of
    (before, remaining)
      | ByteString.null remaining -> input
      | otherwise -> before <> replacement <> ByteString.drop (ByteString.length needle) remaining

componentBody :: ByteString
componentBody =
  ByteString8.unlines
    [ "library"
    , "  exposed-modules: Only"
    , "  hs-source-dirs: src"
    , "  default-language: GHC2024"
    ]

executableCabal :: ByteString
executableCabal =
  packageHeader "Simple"
    <> ByteString8.unlines
      [ "executable tool"
      , "  main-is: Main.hs"
      , "  hs-source-dirs: app"
      , "  default-language: GHC2024"
      ]

packageHeader :: ByteString -> ByteString
packageHeader buildType =
  ByteString8.unlines
    [ "cabal-version: 3.0"
    , "name: component-plan-oracle"
    , "version: 0.1.0.0"
    , "build-type: " <> buildType
    ]

numberedEntries :: Int -> [WireEntry]
numberedEntries count = [wire ("entry/e" <> pad3 index <> ".txt") "" | index <- [1 .. count]]

aggregateEntries :: [Int] -> [WireEntry]
aggregateEntries sizes =
  [wire ("blob/b" <> pad3 index <> ".bin") (ByteString.replicate size 97) | (index, size) <- zip [1 :: Int ..] sizes]

invalidCabalEntries :: Int -> [WireEntry]
invalidCabalEntries count = [wire ("p" <> show index <> ".cabal") "!" | index <- [1 .. count]]

repeatedLines :: Int -> ByteString -> ByteString
repeatedLines count value = ByteString8.unlines (replicate count value)

fieldLine :: ByteString -> Int -> ByteString -> ByteString
fieldLine field count prefix = field <> ": " <> ByteString8.unwords [prefix <> ByteString8.pack (pad3 index) | index <- [1 .. count]] <> "\n"

commaFieldLine :: ByteString -> Int -> ByteString -> ByteString
commaFieldLine field count prefix = field <> ": " <> ByteString8.intercalate ", " [prefix <> ByteString8.pack (pad3 index) | index <- [1 .. count]] <> "\n"

compactCommaFieldLine :: ByteString -> Int -> ByteString -> ByteString
compactCommaFieldLine field count prefix = field <> ": " <> ByteString8.intercalate "," [prefix <> ByteString8.pack (pad3 index) | index <- [1 .. count]] <> "\n"

pad3 :: Int -> String
pad3 value = replicate (3 - length rendered) '0' <> rendered
 where
  rendered = show value

aggregateBytes :: [WireEntry] -> Int
aggregateBytes = foldl' (\total entry -> total + ByteString.length (wireBytes entry)) 0

inventorySha256 :: [WireEntry] -> Text
inventorySha256 entries =
  digestChunks
    (Crypto.hashInit :: Crypto.Context Crypto.SHA256)
    ("amoebius.compiler-component-plan.raw.v1\0" : concatMap wireChunks entries)

wireChunks :: WireEntry -> [ByteString]
wireChunks entry =
  [ TextEncoding.encodeUtf8 (wireMode entry)
  , "\0"
  , TextEncoding.encodeUtf8 (wireObjectIdentity entry)
  , "\0"
  , TextEncoding.encodeUtf8 (Text.pack (wirePath entry))
  , "\0"
  , ByteString8.pack (show (ByteString.length (wireBytes entry)))
  , "\0"
  , wireBytes entry
  , "\0"
  ]

projectionSha256 :: Text -> [Text] -> [ProjectionAssignment] -> [Finding] -> Text
projectionSha256 identity components assignments problems =
  digestChunks
    (Crypto.hashInit :: Crypto.Context Crypto.SHA256)
    ( "amoebius.compiler-component-plan.projection.v1\0"
        : fieldChunk identity
        <> concatMap fieldChunk components
        <> concatMap projectionAssignmentChunks assignments
        <> concatMap (fieldChunk . renderProblem) problems
    )

projectionAssignmentChunks :: ProjectionAssignment -> [ByteString]
projectionAssignmentChunks projected =
  fieldChunk (projectionAssignmentName projected)
    <> fieldChunk (projectionAssignmentKind projected)
    <> fieldChunk (Text.pack (projectionAssignmentPath projected))
    <> fieldChunk (projectionAssignmentMode projected)
    <> fieldChunk (projectionAssignmentObjectIdentity projected)
    <> concatMap fieldChunk (projectionAssignmentModules projected)
    <> concatMap (fieldChunk . Text.pack) (projectionAssignmentSourceDirectories projected)
    <> maybe (fieldChunk "<none>") fieldChunk (projectionAssignmentLanguage projected)
    <> concatMap fieldChunk (projectionAssignmentExtensions projected)
    <> concatMap fieldChunk (projectionAssignmentGhcOptions projected)
    <> concatMap fieldChunk (projectionAssignmentCppOptions projected)
    <> concatMap fieldChunk (projectionAssignmentDependencies projected)
    <> concatMap projectionConfigChunks (projectionAssignmentExtraConfigs projected)

projectionConfigChunks :: ProjectionConfig -> [ByteString]
projectionConfigChunks (ProjectionConfig sourceDirectories languageValue extensions ghcOptions cppOptions dependencies) =
  concatMap (fieldChunk . Text.pack) sourceDirectories
    <> maybe (fieldChunk "<none>") fieldChunk languageValue
    <> concatMap fieldChunk extensions
    <> concatMap fieldChunk ghcOptions
    <> concatMap fieldChunk cppOptions
    <> concatMap fieldChunk dependencies

fieldChunk :: Text -> [ByteString]
fieldChunk value = [ByteString8.pack (show (ByteString.length encoded)), ":", encoded, "\0"]
 where
  encoded = TextEncoding.encodeUtf8 value

renderProblem :: Finding -> Text
renderProblem item = findingCode item <> "\t" <> Text.pack (findingSubject item) <> "\t" <> findingDetail item

gitBlobSha1, gitBlobSha256 :: ByteString -> Text
gitBlobSha1 bytes = digestChunks (Crypto.hashInit :: Crypto.Context Crypto.SHA1) [gitHeader bytes, bytes]
gitBlobSha256 bytes = digestChunks (Crypto.hashInit :: Crypto.Context Crypto.SHA256) [gitHeader bytes, bytes]

gitHeader :: ByteString -> ByteString
gitHeader bytes = ByteString8.pack ("blob " <> show (ByteString.length bytes) <> "\0")

digestChunks
  :: Crypto.HashAlgorithm algorithm
  => Crypto.Context algorithm
  -> [ByteString]
  -> Text
digestChunks initial chunks = Text.pack (show (Crypto.hashFinalize (foldl' Crypto.hashUpdate initial chunks)))

decimalText :: Int -> Text
decimalText = Text.pack . show

zeroIdentity :: Text
zeroIdentity = Text.replicate 64 "0"

supportedCabalObjectLiteral, supportedSourceObjectLiteral, supportedInventoryLiteral, supportedProjectionLiteral :: Text
supportedCabalObjectLiteral = "65f9c326319404cca626a8ca9d65ef6b919aec45"
supportedSourceObjectLiteral = "3f6d5b42c59eb6ce24271de751e0d1ba10984851"
supportedInventoryLiteral = "cca4095c47a7bb78b700ba1aa1815d2f165ba666bfc023e77de39d732dd85966"
supportedProjectionLiteral = "626bbd8431e79272b10513c4d7d166b24dd341a5b920f61ee7d6d8429d19a384"

fixtureIntegrityProblems :: [String]
fixtureIntegrityProblems =
  concat
    [ expectEqual "literal supported Cabal Git object" supportedCabalObjectLiteral (gitBlobSha1 supportedCabal)
    , expectEqual "literal supported source Git object" supportedSourceObjectLiteral (gitBlobSha1 supportedSource)
    , expectEqual "literal supported inventory SHA-256" supportedInventoryLiteral (inventorySha256 supportedEntries)
    , expectEqual
        "literal supported projection SHA-256"
        supportedProjectionLiteral
        (projectionSha256 supportedInventoryLiteral ["lib"] [supportedAssignment] [])
    , expectEqual "snapshot-entry max fixture" 128 (length (numberedEntries 128))
    , expectEqual "snapshot-entry max+1 fixture" 129 (length (numberedEntries 129))
    , expectEqual "path-byte max fixture" 240 (length (replicate 236 'a' <> ".txt"))
    , expectEqual "path-byte max+1 fixture" 241 (length (replicate 237 'a' <> ".txt"))
    , expectEqual "blob-byte max fixture" 65536 (ByteString.length (ByteString.replicate 65536 97))
    , expectEqual "blob-byte max+1 fixture" 65537 (ByteString.length (ByteString.replicate 65537 97))
    , expectEqual "aggregate-byte max fixture" 262144 (aggregateBytes (aggregateEntries [52429, 52429, 52429, 52429, 52428]))
    , expectEqual "aggregate-byte max+1 fixture" 262145 (aggregateBytes (aggregateEntries (replicate 5 52429)))
    , expectEqual "Cabal-entry max fixture" 4 (length (invalidCabalEntries 4))
    , expectEqual "Cabal-entry max+1 fixture" 5 (length (invalidCabalEntries 5))
    ]

expectEqual :: (Eq value, Show value) => String -> value -> value -> [String]
expectEqual label expected actual
  | expected == actual = []
  | otherwise = [label <> ": expected " <> show expected <> ", observed " <> show actual]

finishDiagnostics :: String -> [String] -> IO ()
finishDiagnostics name problems = do
  unless (null problems) (fail (unlines (name : problems)))
  putStrLn
    ( name
        <> ": exact raw diagnostics, resource/grammar boundaries, projections, and mandatory residue agree; no evidence was minted."
    )
